do $$ begin if exists (select 1 from public.gateway_payment_attempts where transaction_id is null) then raise exception 'gateway_attempt_transaction_id_null_rows_exist'; end if; alter table public.gateway_payment_attempts alter column transaction_id set not null; end $$; create index if not exists idx_gateway_payment_attempts_transaction_tenant on public.gateway_payment_attempts(user_id, transaction_id, attempt_order);